const OFFLINE_APP=new URLSearchParams(location.search).get("offline")==="1";
const KEY=OFFLINE_APP?"rida_fabrics_offline_v1":"rida_fabrics_pro_v3";
const DEFAULT_PERMS=["dashboard","products:view","products:add","products:edit","products:delete","categories","units","purchases:view","purchases:add","suppliers","sales:view","sales:add","sales:void","customers","employees","expenses:view","expenses:add","expenses:delete","reports","settings","pos","restaurant","inventory","ledgers","cash","returns","alerts","activity","shopkeeper","shopkeeperManagement"];
const DEFAULT_DB={
  settings:{currency:"Rs",primary:"#6F12A0"},
  businesses:[{id:"b1",name:"Rida Fabrics",type:"Clothing & Fabrics",currency:"Rs"}],
  currentBusiness:"b1",
  users:[{id:"u1",name:"Super Admin",username:"",password:"",role:"Super Admin",active:true,permissions:["all"]}],
  roles:[{id:"r1",name:"Admin",permissions:DEFAULT_PERMS.slice()},{id:"r2",name:"Manager",permissions:["dashboard","products:view","products:add","products:edit","categories","units","purchases:view","purchases:add","suppliers","sales:view","sales:add","customers","employees","expenses:view","expenses:add","reports","shopkeeper","shopkeeperManagement"]},{id:"r3",name:"Sales Staff",permissions:["dashboard","products:view","sales:view","sales:add","customers","shopkeeper"]}],
  products:[],categories:["Unstitched","Stitched","3-Piece Suit","2-Piece Suit","Silk","Lawn","Cotton","Other"],units:["Piece","Gaz","Shalwar","Suit","Thaan"],paymentMethods:["Cash","Card","Bank Transfer","Credit"],
  sales:[],purchases:[],expenses:[],expenseCategories:["Rent","Electricity","Transport","Salary","Packaging","Marketing","Maintenance","Other"],suppliers:[],customers:[],employees:[]
};
let db=JSON.parse(localStorage.getItem(KEY)||"null")||DEFAULT_DB;
function migrate(){
  db.settings ||= {currency:"Rs",primary:"#6F12A0"}; db.businesses ||= DEFAULT_DB.businesses;
  if(["#b88a2d","#b58a34","#bc933e","#b4862b"].includes(String(db.settings.primary||"").toLowerCase()))db.settings.primary="#6F12A0";
  db.users ||= DEFAULT_DB.users; db.roles ||= DEFAULT_DB.roles; db.products ||= []; db.categories ||= DEFAULT_DB.categories;
  db.units ||= DEFAULT_DB.units; db.paymentMethods ||= DEFAULT_DB.paymentMethods; db.sales ||= []; db.purchases ||= [];
  db.expenses ||= []; db.expenseCategories ||= DEFAULT_DB.expenseCategories; db.suppliers ||= []; db.customers ||= []; db.employees ||= [];
  db.restaurantTables ||= []; db.restaurantOrders ||= [];
  db.products.forEach(x=>{x.businessId ||= db.currentBusiness;x.unit ||= "Piece";x.category ||= "Other"});
  db.sales.forEach(x=>x.businessId ||= db.currentBusiness); db.purchases.forEach(x=>x.businessId ||= db.currentBusiness);
  db.expenses.forEach(x=>x.businessId ||= db.currentBusiness); db.suppliers.forEach(x=>x.businessId ||= db.currentBusiness);
  db.customers.forEach(x=>x.businessId ||= db.currentBusiness); db.employees.forEach(x=>x.businessId ||= db.currentBusiness);
  db.currentBusiness ||= "b1"; localStorage.setItem(KEY,JSON.stringify(db));
}
migrate();
if(OFFLINE_APP){let owner=db.users?.[0]||{id:Date.now().toString(36),permissions:["all"]};owner={...owner,name:"Offline Owner",username:"",password:"",role:"Offline Owner",active:true,permissions:["all"]};db.users=[owner];db.currentUser=owner.id;localStorage.setItem(KEY,JSON.stringify(db))}
const $=id=>document.getElementById(id),uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7),today=()=>new Date().toISOString().slice(0,10);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&gt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]||c));
const biz=()=>db.currentBusiness, B=()=>db.businesses.find(x=>x.id===biz()), money=n=>`${B()?.currency||db.settings.currency||"Rs"} ${Number(n||0).toLocaleString("en-PK",{maximumFractionDigits:2})}`;
const arr=(name)=>db[name].filter(x=>!x.businessId||x.businessId===biz());
function save(){localStorage.setItem(KEY,JSON.stringify(db));applyTheme();renderAll()}
function toast(s){$("toast").textContent=s;$("toast").classList.add("show");setTimeout(()=>$("toast").classList.remove("show"),1800)}
function applyTheme(){document.documentElement.style.setProperty("--gold",db.settings.primary||"#6F12A0");document.documentElement.style.setProperty("--accent","#C602A2");document.documentElement.style.setProperty("--gold-dark","#4E0C70");$("brandName").textContent="Pleniora AI";$("businessPill").textContent=B()?.name||"Pleniora AI"}
function currentUser(){return db.users.find(x=>x.id===db.currentUser)}
function can(p){let u=currentUser();if(!u)return false;if(u.permissions?.includes("all")||u.role==="Super Admin")return true;return u.permissions?.includes(p)||u.permissions?.includes(p.split(":")[0])}
function setUser(){let u=currentUser();if(!u)return;$("userName").textContent=u.name;$("userRole").textContent=u.role;$("avatar").textContent=u.name.split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase();document.querySelectorAll(".super-only").forEach(x=>x.style.display=u.role==="Super Admin"||u.role==="Offline Owner"?"":"none")}
function login(e){e.preventDefault();let u=db.users.find(x=>x.username===$("loginUser").value.trim()&&x.password===$("loginPass").value&&x.active);if(!u)return toast("Invalid username or password");db.currentUser=u.id;localStorage.setItem(KEY,JSON.stringify(db));$("loginScreen").style.display="none";renderAll()}
function logout(){db.currentUser=null;localStorage.setItem(KEY,JSON.stringify(db));$("loginScreen").style.display="grid"}
const TITLES={dashboard:"Dashboard",pos:"Point of Sale",restaurant:"Tables & Orders",inventory:"Inventory Control",products:"Products & Stock",sales:"Daily Sales",shopkeeper:"Shopkeeper Sales",shopkeeperManagement:"دکاندار مینجمنٹ",purchases:"Purchases",suppliers:"Suppliers",customers:"Customers",ledgers:"Ledgers & Accounts",employees:"Employees",expenses:"Daily Expenses",cash:"Cash Register",returns:"Returns & Refunds",alerts:"Tasks & Alerts",reports:"Reports",admins:"Admin Management",business:"Business Setup",customize:"Customization",backup:"Settings & Backup",activity:"Activity Log"};
function showPage(p){const permission=p;if(p==="shopkeeperManagement"&&!/clothing|fabric|fashion|apparel/i.test(B()?.type||''))return toast("Shopkeeper management is available for clothing businesses.");if(!can(permission)&&p!=="dashboard"&&p!=="backup")return toast("Permission denied");document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));$(p).classList.add("active");document.querySelectorAll("#mainNav button").forEach(x=>x.classList.toggle("active",x.dataset.page===p));$("pageTitle").textContent=TITLES[p]||p;renderAll();if(p==="restaurant")window.renderRestaurant?.();window.toggleAppNav?.(false)}
document.querySelectorAll("#mainNav button").forEach(b=>b.onclick=()=>showPage(b.dataset.page));$("today").textContent=new Date().toLocaleDateString("en-PK",{weekday:"long",year:"numeric",month:"long",day:"numeric"});
function toggleAppNav(force){let open=typeof force==="boolean"?force:!document.body.classList.contains("nav-open");document.body.classList.toggle("nav-open",open);let b=$("navToggle");if(b){b.setAttribute("aria-expanded",String(open));b.setAttribute("aria-label",open?"Close navigation":"Open navigation")}}
function openModal(h){$("modalBox").innerHTML=h;$("modal").classList.add("show")}function closeModal(){$("modal").classList.remove("show")}
function opts(a,selected){return a.map(x=>`<option value="${esc(x)}" ${x===selected?"selected":""}>${esc(x)}</option>`).join("")}
function openProduct(id){if(!can(id?"products:edit":"products:add"))return toast("Permission denied");let p=arr("products").find(x=>x.id===id)||{id:"",sku:"",name:"",category:db.categories[0]||"Other",type:"",color:"",size:"",unit:db.units[0]||"Piece",qty:0,minQty:3,buy:0,sale:0,batchNumber:"",expiryDate:"",serialNumber:"",warrantyMonths:""};openModal(`<div class="modalhead"><h3>${id?"Edit":"Add"} Product</h3><button class="close" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>SKU / Barcode</label><input id="pSku" value="${esc(p.sku)}"></div><div class="field"><label>Product name / menu item</label><input id="pName" value="${esc(p.name)}"></div><div class="field"><label>Category</label><select id="pCat">${opts(db.categories,p.category)}</select></div><div class="field"><label>Product type / description</label><input id="pType" value="${esc(p.type)}"></div><div class="field"><label>Color / Design</label><input id="pColor" value="${esc(p.color)}"></div><div class="field"><label>Size / Variant</label><input id="pSize" value="${esc(p.size)}"></div><div class="field"><label>Unit</label><select id="pUnit">${opts(db.units,p.unit)}</select></div><div class="field"><label>Quantity</label><input id="pQty" type="number" min="0" value="${p.qty}"></div><div class="field"><label>Low-stock alert</label><input id="pMin" type="number" min="0" value="${p.minQty}"></div><div class="field"><label>Purchase price</label><input id="pBuy" type="number" min="0" value="${p.buy}"></div><div class="field"><label>Sale price</label><input id="pSale" type="number" min="0" value="${p.sale}"></div><div class="field"><label>Batch / Lot number</label><input id="pBatch" value="${esc(p.batchNumber||"")}" placeholder="Optional"></div><div class="field"><label>Expiry date</label><input id="pExpiry" type="date" value="${esc(p.expiryDate||"")}"></div><div class="field"><label>Serial number</label><input id="pSerial" value="${esc(p.serialNumber||"")}" placeholder="Optional"></div><div class="field"><label>Warranty (months)</label><input id="pWarranty" type="number" min="0" value="${esc(p.warrantyMonths||"")}" placeholder="Optional"></div></div><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveProduct('${id||""}')">Save Product</button></div>`)}
function saveProduct(id){let p={id:id||uid(),businessId:biz(),sku:$("pSku").value.trim(),name:$("pName").value.trim(),category:$("pCat").value,type:$("pType").value.trim(),color:$("pColor").value.trim(),size:$("pSize").value.trim(),unit:$("pUnit").value,qty:+$("pQty").value||0,minQty:+$("pMin").value||0,buy:+$("pBuy").value||0,sale:+$("pSale").value||0,batchNumber:$("pBatch").value.trim(),expiryDate:$("pExpiry").value,serialNumber:$("pSerial").value.trim(),warrantyMonths:+$("pWarranty").value||0};if(!p.name)return toast("Product name required");let i=db.products.findIndex(x=>x.id===p.id);i>=0?db.products[i]=p:db.products.push(p);closeModal();save();toast("Product saved")}
function renderProducts(){let q=$("productSearch")?.value||"",all=arr("products"),a=all.filter(p=>p.archived!==true&&(p.name+" "+p.sku+" "+p.category+" "+p.type+" "+p.color+" "+p.batchNumber+" "+p.serialNumber).toLowerCase().includes(q.toLowerCase()));$("productsBody").innerHTML=a.length?a.map(p=>`<tr><td>${esc(p.sku)}</td><td><b>${esc(p.name)}</b><br><span class="muted">${esc(p.color)} ${esc(p.size)}${p.batchNumber?` · Lot ${esc(p.batchNumber)}`:""}${p.serialNumber?` · S/N ${esc(p.serialNumber)}`:""}${p.expiryDate?` · Exp ${esc(p.expiryDate)}`:""}${p.warrantyMonths?` · ${p.warrantyMonths} mo warranty`:""}</span></td><td>${esc(p.category)}</td><td>${esc(p.type)}</td><td>${p.qty} ${esc(p.unit)}</td><td>${money(p.buy)}</td><td>${money(p.customerSale??p.sale)}${/^(gaz|gaj|گز)$/i.test(String(p.unit||""))?" / Gaz":""}</td><td>${money(p.shopkeeperSale??p.sale)}${/^(gaz|gaj|گز)$/i.test(String(p.unit||""))?" / Gaz":""}</td><td><span class="badge ${p.qty<=p.minQty?"low":"ok"}">${p.qty<=p.minQty?"Low stock":"In stock"}</span></td><td><button class="btn" onclick="openProduct('${p.id}')">Edit</button> <button class="btn danger" onclick="archiveProduct('${p.id}')">Delete</button></td></tr>`).join(""):`<tr><td colspan="10" class="empty">No active products match this search.</td></tr>`;renderArchivedProducts()}
function archiveProduct(id){if(!can("products:delete"))return toast("Product delete permission required");const p=arr("products").find(x=>x.id===id&&!x.archived);if(!p)return;if(!confirm(`Delete ${p.name} from active products? It will be archived so past sales, returns and stock history stay intact.`))return;p.archived=true;p.archivedAt=new Date().toISOString();if(typeof audit==="function")audit("Product archived",`${p.name} · ${p.sku||p.id}`);save();toast("Product deleted from active list. Restore it from Archived products.")}
function restoreProduct(id){if(!can("products:delete"))return toast("Product delete permission required");const p=arr("products").find(x=>x.id===id&&x.archived);if(!p)return;p.archived=false;delete p.archivedAt;if(typeof audit==="function")audit("Product restored",`${p.name} · ${p.sku||p.id}`);save();toast("Product restored")}
function renderArchivedProducts(){const body=$("archivedProductsBody");if(!body)return;const a=arr("products").filter(p=>p.archived);$("archivedProductCount").textContent=`(${a.length})`;body.innerHTML=a.map(p=>`<tr><td>${esc(p.sku||"")}</td><td>${esc(p.name)}</td><td>${esc(p.unit||"")}</td><td>${money(p.sale)}</td><td><button class="btn" onclick="restoreProduct('${p.id}')">Restore</button></td></tr>`).join("")||`<tr><td colspan="5" class="empty">No archived products.</td></tr>`}
function openSale(){if(!can("sales:add"))return toast("Permission denied");let products=arr("products");if(!products.length)return toast("Add products first");let o=products.map(p=>`<option value="${p.id}">${esc(p.name)} — ${money(p.sale)} — stock ${p.qty} ${p.unit}</option>`).join("");openModal(`<div class="modalhead"><h3>New Sale</h3><button class="close" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>Customer</label><select id="sCustomer"><option value="">Walk-in customer</option>${arr("customers").map(c=>`<option value="${c.id}">${esc(c.name)} — ${esc(c.phone)}</option>`).join("")}</select></div><div class="field"><label>Payment</label><select id="sPayment">${opts(db.paymentMethods,db.paymentMethods[0])}</select></div><div class="field"><label>Date</label><input id="sDate" type="date" value="${today()}"></div><div class="field"><label>Discount</label><input id="sDiscount" type="number" value="0" oninput="calcSale()"></div></div><div id="saleLines"><div class="line"><div class="field"><label>Product</label><select class="liProduct" onchange="linePrice(this);calcSale()">${o}</select></div><div class="field"><label>Qty</label><input class="liQty" type="number" min="1" value="1" oninput="calcSale()"></div><div class="field"><label>Price</label><input class="liPrice" type="number" value="${products[0].sale}" oninput="calcSale()"></div><button class="close" onclick="this.parentElement.remove();calcSale()">×</button></div></div><button class="btn" onclick="addSaleLine()">+ Add item</button><div class="summary">Total: <span id="saleTotal">${money(products[0].sale)}</span></div><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveSale()">Save Sale</button></div>`)}
function addSaleLine(){let products=arr("products").filter(p=>!p.archived),o=products.map(p=>`<option value="${p.id}">${esc(p.name)} — ${money(p.sale)} — stock ${p.qty}</option>`).join(""),d=document.createElement("div");d.className="line";d.innerHTML=`<div class="field"><label>Product</label><select class="liProduct" onchange="linePrice(this);calcSale()">${o}</select></div><div class="field"><label>Qty</label><input class="liQty" type="number" min="1" value="1" oninput="calcSale()"></div><div class="field"><label>Price</label><input class="liPrice" type="number" value="${products[0].sale}" oninput="calcSale()"></div><button class="close" onclick="this.parentElement.remove();calcSale()">×</button>`;$("saleLines").appendChild(d)}
function linePrice(s){let p=arr("products").find(x=>x.id===s.value);s.closest(".line").querySelector(".liPrice").value=p?.sale||0}function calcSale(){let t=0;document.querySelectorAll(".line").forEach(l=>t+=(+l.querySelector(".liQty").value||0)*(+l.querySelector(".liPrice").value||0));t-=+$("sDiscount")?.value||0;if($("saleTotal"))$("saleTotal").textContent=money(Math.max(0,t))}
function saveSale(){let lines=[...document.querySelectorAll(".line")].map(l=>({productId:l.querySelector(".liProduct").value,qty:+l.querySelector(".liQty").value||0,price:+l.querySelector(".liPrice").value||0}));for(let l of lines){let p=arr("products").find(x=>x.id===l.productId);if(!p||l.qty>p.qty)return toast("Not enough stock");}let discount=+$("sDiscount").value||0,total=Math.max(0,lines.reduce((a,l)=>a+l.qty*l.price,0)-discount),cost=lines.reduce((a,l)=>a+l.qty*(arr("products").find(p=>p.id===l.productId)?.buy||0),0),customerId=$("sCustomer").value;lines.forEach(l=>arr("products").find(p=>p.id===l.productId).qty-=l.qty);db.sales.unshift({id:uid(),businessId:biz(),invoice:"RF-"+Date.now().toString().slice(-6),date:$("sDate").value,customerId,customer:arr("customers").find(c=>c.id===customerId)?.name||"Walk-in",payment:$("sPayment").value,lines,total,cost,profit:total-cost});closeModal();save();toast("Sale saved & stock updated")}
function renderSales(){let q=($("salesSearch")?.value||"").toLowerCase(),a=arr("sales").filter(s=>(s.invoice+" "+s.customer).toLowerCase().includes(q));$("salesBody").innerHTML=a.length?a.map(s=>`<tr><td>${s.date}</td><td>${s.invoice}</td><td>${esc(s.customer)}</td><td>${s.lines.reduce((a,x)=>a+x.qty,0)}</td><td>${money(s.total)}</td><td>${s.payment}</td><td><button class="btn danger" onclick="voidSale('${s.id}')">Void</button></td></tr>`).join(""):`<tr><td colspan="7" class="empty">No sales.</td></tr>`}
function voidSale(id){if(!can("sales:void"))return toast("Permission denied");let s=arr("sales").find(x=>x.id===id);if(!s||!confirm("Void sale and return stock?"))return;s.lines.forEach(l=>{let p=arr("products").find(x=>x.id===l.productId);if(p)p.qty+=l.qty});db.sales=db.sales.filter(x=>x.id!==id);save()}
function openSupplier(id){if(!can("suppliers"))return toast("Permission denied");let s=arr("suppliers").find(x=>x.id===id)||{id:"",name:"",company:"",phone:"",address:"",opening:0};openModal(`<div class="modalhead"><h3>${id?"Edit":"Add"} Supplier</h3><button class="close" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>Supplier name</label><input id="spName" value="${esc(s.name)}"></div><div class="field"><label>Company</label><input id="spCompany" value="${esc(s.company)}"></div><div class="field"><label>Phone / WhatsApp</label><input id="spPhone" value="${esc(s.phone)}"></div><div class="field full"><label>Address</label><input id="spAddress" value="${esc(s.address)}"></div><div class="field"><label>Opening payable</label><input id="spOpening" type="number" value="${s.opening||0}"></div></div><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveSupplier('${id||""}')">Save Supplier</button></div>`)}
function saveSupplier(id){let s={id:id||uid(),businessId:biz(),name:$("spName").value.trim(),company:$("spCompany").value.trim(),phone:$("spPhone").value.trim(),address:$("spAddress").value.trim(),opening:+$("spOpening").value||0};if(!s.name)return toast("Supplier name required");let i=db.suppliers.findIndex(x=>x.id===s.id);i>=0?db.suppliers[i]=s:db.suppliers.push(s);closeModal();save()}
function supplierPayable(id){let s=arr("suppliers").find(x=>x.id===id);if(!s)return 0;let purchases=arr("purchases").filter(p=>p.supplierId===id).reduce((a,x)=>a+x.total-(x.paid||0),0);return (s.opening||0)+purchases}
function renderSuppliers(){$("suppliersBody").innerHTML=arr("suppliers").map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${esc(s.phone)}</td><td>${esc(s.company)}</td><td>${money(supplierPayable(s.id))}</td><td><button class="btn" onclick="openSupplier('${s.id}')">Edit</button></td></tr>`).join("")||`<tr><td colspan="5" class="empty">No suppliers.</td></tr>`}
function openPurchase(){if(!can("purchases:add"))return toast("Permission denied");let suppliers=arr("suppliers"),products=arr("products").filter(p=>!p.archived);if(!suppliers.length)return toast("Add a supplier first");if(!products.length)return toast("Add products first");let so=suppliers.map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.company)}</option>`).join(""),po=products.map(p=>`<option value="${p.id}">${esc(p.name)} — stock ${p.qty}</option>`).join("");openModal(`<div class="modalhead"><h3>New Purchase</h3><button class="close" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>Supplier</label><select id="puSupplier">${so}</select></div><div class="field"><label>Payment</label><select id="puPayment">${opts(db.paymentMethods,db.paymentMethods[0])}</select></div><div class="field"><label>Date</label><input id="puDate" type="date" value="${today()}"></div><div class="field"><label>Paid</label><input id="puPaid" type="number" value="0" oninput="calcPurchase()"></div></div><div id="purchaseLines"><div class="line"><div class="field"><label>Product</label><select class="puProduct">${po}</select></div><div class="field"><label>Qty</label><input class="puQty" type="number" min="1" value="1" oninput="calcPurchase()"></div><div class="field"><label>Buy Price</label><input class="puPrice" type="number" value="${products[0].buy}" oninput="calcPurchase()"></div><button class="close" onclick="this.parentElement.remove();calcPurchase()">×</button></div></div><button class="btn" onclick="addPurchaseLine()">+ Add item</button><div class="summary">Total: <span id="purchaseTotal">${money(products[0].buy)}</span></div><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="savePurchase()">Save Purchase</button></div>`)}
function addPurchaseLine(){let products=arr("products").filter(p=>!p.archived),o=products.map(p=>`<option value="${p.id}">${esc(p.name)} — stock ${p.qty}</option>`).join(""),d=document.createElement("div");d.className="line";d.innerHTML=`<div class="field"><label>Product</label><select class="puProduct">${o}</select></div><div class="field"><label>Qty</label><input class="puQty" type="number" min="1" value="1" oninput="calcPurchase()"></div><div class="field"><label>Buy Price</label><input class="puPrice" type="number" value="${products[0].buy}" oninput="calcPurchase()"></div><button class="close" onclick="this.parentElement.remove();calcPurchase()">×</button>`;$("purchaseLines").appendChild(d)}
function calcPurchase(){let t=0;document.querySelectorAll("#purchaseLines .line").forEach(l=>t+=(+l.querySelector(".puQty").value||0)*(+l.querySelector(".puPrice").value||0));if($("purchaseTotal"))$("purchaseTotal").textContent=money(t)}
function savePurchase(){let lines=[...document.querySelectorAll("#purchaseLines .line")].map(l=>({productId:l.querySelector(".puProduct").value,qty:+l.querySelector(".puQty").value||0,price:+l.querySelector(".puPrice").value||0})),total=lines.reduce((a,l)=>a+l.qty*l.price,0),paid=+$("puPaid").value||0;if(!lines.length||!total)return toast("Add purchase items");lines.forEach(l=>{let p=arr("products").find(x=>x.id===l.productId);p.qty+=l.qty;p.buy=l.price});db.purchases.unshift({id:uid(),businessId:biz(),date:$("puDate").value,supplierId:$("puSupplier").value,total,paid,payment:$("puPayment").value,lines});closeModal();save();toast("Purchase saved & stock increased")}
function renderPurchases(){$("purchasesBody").innerHTML=arr("purchases").map(p=>`<tr><td>${p.date}</td><td>${esc(arr("suppliers").find(s=>s.id===p.supplierId)?.name||"")}</td><td>${p.lines.reduce((a,x)=>a+x.qty,0)}</td><td>${money(p.total)}</td><td>${p.payment}</td><td><button class="btn danger" onclick="deletePurchase('${p.id}')">Delete</button></td></tr>`).join("")||`<tr><td colspan="6" class="empty">No purchases.</td></tr>`}
function deletePurchase(id){if(!can("purchases:add"))return toast("Permission denied");let p=arr("purchases").find(x=>x.id===id);if(!p||!confirm("Delete purchase and reverse stock?"))return;p.lines.forEach(l=>{let pr=arr("products").find(x=>x.id===l.productId);if(pr)pr.qty=Math.max(0,pr.qty-l.qty)});db.purchases=db.purchases.filter(x=>x.id!==id);save()}
